mapper.select:


	
		AND p.plan_name like concat('%', #{planName}, '%')
	
	
		AND p.cycle_type = #{cycleType}
	
	
		AND p.plan_status = #{planStatus}
	
	
		AND date_format(p.start_date,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
	
	
		AND date_format(p.start_date,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
	

order by p.plan_id desc
